-- Hoy, si se reasigna un vehículo a otro transportista y luego alguien vuelve a darle clic a "Generar prefacturas del período" (algo normal, para traer ODT nuevas), generar_prefacturas_periodo actualiza en silencio el transportista_id de una prefactura que YA tenía PDF generado/enviado, sin marcarla para regenerar ni avisar — el PDF ya emitido queda mostrando al transportista viejo sin que nada lo señale. Igual que una corrección de ODT, este cambio ahora marca REQUIERE_REGENERAR (nunca sobre una ANULADA) y además informa cuántas prefacturas quedaron así.
-- Agrega una tercera columna al retorno (prefacturas_requieren_regenerar): Postgres no permite cambiar el tipo de retorno de una función existente solo con CREATE OR REPLACE, así que hay que borrarla primero (el DROP es seguro: no toca ninguna tabla ni dato, solo la definición de la función, que se vuelve a crear en la siguiente línea).
drop function if exists public.generar_prefacturas_periodo(uuid);
create or replace function public.generar_prefacturas_periodo(p_periodo_id uuid) returns table (prefacturas_creadas integer, prefacturas_actualizadas integer, prefacturas_requieren_regenerar integer) language plpgsql security invoker set search_path = public as $$ declare v_creadas integer := 0; v_actualizadas integer := 0; v_requieren_regenerar integer := 0; begin update odt o set vehiculo_id = v.id from vehiculo v where o.periodo_id = p_periodo_id and o.vehiculo_id is null and o.placa_normalizada = v.placa and v.deleted_at is null; with previos as (select p.id, p.vehiculo_id, p.transportista_id, p.estado, exists (select 1 from documento_pdf dp where dp.prefactura_id = p.id and dp.estado = 'VIGENTE') as tiene_pdf_vigente from prefactura p where p.periodo_id = p_periodo_id and p.es_principal), descuentos_odt as (select odt_id, sum(valor) as valor from descuento where deleted_at is null group by odt_id), agregado as (select o.vehiculo_id, v.transportista_id, count(*) as cantidad_odt, sum(coalesce(o.valor_final, o.valor)) as total_odt, coalesce(sum(d.valor), 0) as total_descuentos from odt o join vehiculo v on v.id = o.vehiculo_id left join descuentos_odt d on d.odt_id = o.id where o.periodo_id = p_periodo_id and o.vehiculo_id is not null and v.transportista_id is not null group by o.vehiculo_id, v.transportista_id), upsert as (insert into prefactura (periodo_id, vehiculo_id, transportista_id, total_odt, total_descuentos, total, cantidad_odt, estado) select p_periodo_id, a.vehiculo_id, a.transportista_id, a.total_odt, a.total_descuentos, a.total_odt - a.total_descuentos, a.cantidad_odt, 'BORRADOR' from agregado a on conflict (vehiculo_id, periodo_id) where es_principal do update set total_odt = excluded.total_odt, total_descuentos = excluded.total_descuentos, total = excluded.total_odt - excluded.total_descuentos, cantidad_odt = excluded.cantidad_odt, transportista_id = excluded.transportista_id, estado = case when prefactura.estado in ('BORRADOR', 'CON_NOVEDADES') then 'BORRADOR' when prefactura.estado <> 'ANULADA' and prefactura.transportista_id is distinct from excluded.transportista_id and exists (select 1 from documento_pdf dp where dp.prefactura_id = prefactura.id and dp.estado = 'VIGENTE') then 'REQUIERE_REGENERAR' else prefactura.estado end returning id, (xmax = 0) as es_nuevo, vehiculo_id, transportista_id) select count(*) filter (where u.es_nuevo)::integer, count(*) filter (where not u.es_nuevo)::integer, count(*) filter (where not u.es_nuevo and pr.estado <> 'ANULADA' and pr.tiene_pdf_vigente and pr.transportista_id is distinct from u.transportista_id)::integer into v_creadas, v_actualizadas, v_requieren_regenerar from upsert u left join previos pr on pr.vehiculo_id = u.vehiculo_id; insert into prefactura_detalle (prefactura_id, odt_id) select p.id, o.id from odt o join prefactura p on p.vehiculo_id = o.vehiculo_id and p.periodo_id = p_periodo_id and p.es_principal where o.periodo_id = p_periodo_id and o.vehiculo_id is not null on conflict (prefactura_id, odt_id) do nothing; return query select v_creadas, v_actualizadas, v_requieren_regenerar; end; $$;
comment on function public.generar_prefacturas_periodo(uuid) is 'Botón "Generar prefacturas del período": vincula ODT huérfanas, hace UPSERT de 1 prefactura PRINCIPAL por vehículo (con total_descuentos recalculado desde descuento), congela prefactura_detalle. El correlativo solo se asigna a las nuevas. Si el vehículo cambió de transportista y la prefactura ya tenía PDF vigente (y no está ANULADA), la marca REQUIERE_REGENERAR en vez de actualizarla en silencio.';
